;---------------------------------------------------------------------------------------------------
; ObdPid14_O2Sensor1  ($22E9)
;
; Service 1 PID $14: upstream O2 voltage. [reviewed]
;
; B4C2 sends the raw A/D byte of O2SensorVolts. The other code bases (B559, B4F3, B4CC) first
; scale it by $03ED/256 to the J1979 unit of 5 mV per bit and send $FF from $41 up, so a scan tool
; reads B4C2's O2 voltage about four times too low.
;---------------------------------------------------------------------------------------------------
ObdPid14_O2Sensor1:
        ldaa    >O2SensorVolts
        staa    >IsoRespData1
        ldaa    #$01
        ldab    <Counter_O2SensorFeedbackCount_Signed
        bmi     L2312
        inca
L2312:
        lsrd
        lsrd
        stab    >IsoRespData2
        ldx     #$0495
        jmp     >CODE1f17


